package com.example;

import com.betteritemexamine.BetterItemExaminePlugin;
import com.betteritemexamine.PassiveEffectRepository;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BetterItemExaminePluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(BetterItemExaminePlugin.class);
        RuneLite.main(args);
    }
}

package com.betteritemexamine;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Sanity-checks that passive_effects.json parses cleanly and that the
 * Twisted bow entry (the item this plugin was originally built for) is
 * present. Extend this when you add new items if you want regression
 * coverage.
 */
public class PassiveEffectRepositoryTest
{
	private static final int TWISTED_BOW_ITEM_ID = 20997;

	private PassiveEffectRepository repository;

	@Before
	public void setUp() throws Exception
	{
		repository = new PassiveEffectRepository();

		// Manually inject a Gson instance since we're not spinning up Guice in this test.
		Field gsonField = PassiveEffectRepository.class.getDeclaredField("gson");
		gsonField.setAccessible(true);
		gsonField.set(repository, new Gson());

		repository.load();
	}

	@Test
	public void loadsWithoutError()
	{
		assertFalse("Expected at least one passive effect to be loaded", repository.getAll().isEmpty());
	}

	@Test
	public void twistedBowIsPresent()
	{
		PassiveEffect effect = repository.getForItemId(TWISTED_BOW_ITEM_ID);
		assertNotNull("Twisted bow entry should exist in passive_effects.json", effect);
		assertTrue(effect.getDescription().toLowerCase().contains("magic"));
	}

	@Test
	public void unknownItemReturnsNull()
	{
		assertNotNull(repository.getForItemId(TWISTED_BOW_ITEM_ID));
		assertTrue(repository.getForItemId(-1) == null);
	}
}

package com.betteritemexamine;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Field;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * Validates every passive_effects data file listed in
 * PassiveEffectRepository.DATA_FILES. This is the main safety net for
 * contributors: run `gradlew test` after editing/adding a JSON entry and
 * this will catch the common mistakes (duplicate item ids, missing
 * description, malformed JSON, referencing a file that doesn't exist).
 *
 * If you add a whole new category file, remember to also add it to
 * PassiveEffectRepository.DATA_FILES - this test will fail loudly if you
 * forget, since PassiveEffectRepositoryLoadTest below cross-checks the two.
 */
public class PassiveEffectDataValidationTest
{
	private static final String DATA_DIR = "/com/betteritemexamine/data/";
	private static final int TWISTED_BOW_ITEM_ID = 20997;

	private final Gson gson = new Gson();

	@Test
	public void everyDataFileParsesAndIsWellFormed()
	{
		List<String> errors = new ArrayList<>();
		Map<Integer, String> seenItemIds = new HashMap<>();

		for (String fileName : PassiveEffectRepository.getDataFiles())
		{
			String path = DATA_DIR + fileName;

			try (InputStream is = getClass().getResourceAsStream(path))
			{
				assertNotNull("Data file listed in DATA_FILES was not found on the classpath: " + path, is);

				Type listType = new TypeToken<List<PassiveEffect>>()
				{
				}.getType();

				List<PassiveEffect> effects;
				try (InputStreamReader reader = new InputStreamReader(is, StandardCharsets.UTF_8))
				{
					effects = gson.fromJson(reader, listType);
				}

				if (effects == null || effects.isEmpty())
				{
					errors.add(fileName + ": parsed to empty/null - check for JSON syntax errors");
					continue;
				}

				for (PassiveEffect effect : effects)
				{
					String context = fileName + " / '" + effect.getName() + "'";

					if (effect.getName() == null || effect.getName().isBlank())
					{
						errors.add(context + ": missing 'name'");
					}
					if (effect.getDescription() == null || effect.getDescription().isBlank())
					{
						errors.add(context + ": missing 'description'");
					}
					if (effect.getItemIds() == null || effect.getItemIds().isEmpty())
					{
						errors.add(context + ": missing/empty 'itemIds'");
						continue;
					}

					for (Integer itemId : effect.getItemIds())
					{
						if (itemId == null || itemId <= 0)
						{
							errors.add(context + ": invalid itemId " + itemId);
							continue;
						}

						String owner = fileName + " / " + effect.getName();
						String previousOwner = seenItemIds.putIfAbsent(itemId, owner);
						if (previousOwner != null)
						{
							errors.add("Duplicate item id " + itemId + " claimed by both '"
								+ previousOwner + "' and '" + owner + "'");
						}
					}
				}
			}
			catch (Exception e)
			{
				errors.add(fileName + ": failed to parse - " + e.getMessage());
			}
		}

		if (!errors.isEmpty())
		{
			fail("Passive effect data validation failed:\n  - " + String.join("\n  - ", errors));
		}
	}

	private PassiveEffectRepository repository;

	@Before
	public void setUp() throws Exception
	{
		repository = new PassiveEffectRepository();

		// Manually inject a Gson instance since we're not spinning up Guice in this test.
		Field gsonField = PassiveEffectRepository.class.getDeclaredField("gson");
		gsonField.setAccessible(true);
		gsonField.set(repository, new Gson());

		repository.load();
	}

	@Test
	public void repositoryLoadsAllFiles()
	{
		assertFalse("Expected at least one passive effect to be loaded", repository.getAll().isEmpty());
	}

	@Test
	public void twistedBowIsPresent()
	{
		PassiveEffect effect = repository.getForItemId(TWISTED_BOW_ITEM_ID);
		assertNotNull("Twisted bow entry should exist in weapons.json", effect);
		assertTrue(effect.getDescription().toLowerCase().contains("magic"));
	}

	@Test
	public void unknownItemReturnsNull()
	{
		assertNotNull(repository.getForItemId(TWISTED_BOW_ITEM_ID));
		assertTrue(repository.getForItemId(-1) == null);
	}
}

package com.betteritemexamine;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(BetterItemExamineConfig.GROUP)
public interface BetterItemExamineConfig extends Config
{
	String GROUP = "betteritemexamine";

	@ConfigItem(
		keyName = "appendToExamineText",
		name = "Append to examine text",
		description = "If enabled, the passive effect is appended directly onto the item's examine chat line. "
			+ "If disabled, it is sent as a separate game message instead.",
		position = 1
	)
	default boolean appendToExamineText()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight color",
		description = "Color used to highlight the passive effect text in chat.",
		position = 2
	)
	default Color highlightColor()
	{
		return new Color(0, 200, 255);
	}

	@ConfigItem(
		keyName = "onlyEquippable",
		name = "Only equippable items",
		description = "If enabled, only show passive info for items that can be worn/wielded. "
			+ "Disable to also cover things like non-wearable passive-effect items (e.g. certain rings, tools).",
		position = 3
	)
	default boolean onlyEquippable()
	{
		return false;
	}
}

package com.betteritemexamine;

import java.util.List;
import lombok.Data;

/**
 * Represents a single "hidden" passive effect entry, as loaded from
 * passive_effects.json. One entry can cover multiple item ids, since the
 * same passive often applies to several variants of an item
 * (e.g. broken/degraded charged versions, ornament kits, etc).
 */
@Data
public class PassiveEffect
{
	/**
	 * All item ids this entry applies to. Include every variant you want
	 * covered (uncharged/charged, ornamented, degraded, etc).
	 */
	private List<Integer> itemIds;

	/**
	 * Display name, purely for logging/debugging - not shown to the user.
	 */
	private String name;

	/**
	 * Short description of the passive effect, appended to the examine text.
	 * Keep this reasonably short so it fits comfortably in the chatbox.
	 */
	private String description;

	/**
	 * Optional link to the OSRS Wiki page for this item's mechanics.
	 * Not currently used at runtime, but useful for contributors to track
	 * where a description's numbers came from, and reserved for a future
	 * "open wiki page" right-click option.
	 */
	private String wikiUrl;
}

package com.betteritemexamine;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads passive effect data from every file in DATA_FILES into a single
 * item-id -> PassiveEffect lookup map.
 *
 * Adding entries to any of the existing category files (weapons.json,
 * armour.json, ammunition.json, jewellery.json) needs zero Java changes.
 * Adding a whole new category file needs a one-line addition to DATA_FILES
 * below.
 */
@Slf4j
@Singleton
public class PassiveEffectRepository
{
	private static final String DATA_DIR = "/com/betteritemexamine/data/";

	/**
	 * Every JSON file under DATA_DIR that should be loaded. Add new category
	 * files here as they're created (e.g. "gloves.json").
	 */
	private static final List<String> DATA_FILES = List.of(
		"weapons.json",
		"armour.json",
		"ammunition.json",
		"jewellery.json"
	);

	private final Map<Integer, PassiveEffect> effectsByItemId = new HashMap<>();

	@Inject
	private Gson gson;

	/**
	 * (Re)loads all passive effect data from the bundled JSON resources.
	 * Safe to call multiple times, e.g. on plugin startup.
	 */
	public void load()
	{
		effectsByItemId.clear();

		List<PassiveEffect> allEffects = new ArrayList<>();
		for (String fileName : DATA_FILES)
		{
			allEffects.addAll(loadFile(fileName));
		}

		for (PassiveEffect effect : allEffects)
		{
			if (effect.getItemIds() == null || effect.getItemIds().isEmpty())
			{
				log.warn("Skipping passive effect entry with no itemIds: {}", effect.getName());
				continue;
			}

			for (Integer itemId : effect.getItemIds())
			{
				if (itemId == null)
				{
					continue;
				}

				PassiveEffect existing = effectsByItemId.get(itemId);
				if (existing != null && existing != effect)
				{
					log.warn(
						"Duplicate item id {} claimed by both '{}' and '{}' - the later entry wins. "
							+ "Fix this in the JSON data files.",
						itemId, existing.getName(), effect.getName());
				}

				effectsByItemId.put(itemId, effect);
			}
		}

		log.debug("Loaded {} passive effect entries covering {} item ids", allEffects.size(), effectsByItemId.size());
	}

	private List<PassiveEffect> loadFile(String fileName)
	{
		String path = DATA_DIR + fileName;

		try (InputStream is = getClass().getResourceAsStream(path))
		{
			if (is == null)
			{
				log.warn("Could not find passive effect data file {}", path);
				return Collections.emptyList();
			}

			Type listType = new TypeToken<List<PassiveEffect>>()
			{
			}.getType();

			try (InputStreamReader reader = new InputStreamReader(is, StandardCharsets.UTF_8))
			{
				List<PassiveEffect> effects = gson.fromJson(reader, listType);
				return effects == null ? Collections.emptyList() : effects;
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to load passive effect data from {}", path, e);
			return Collections.emptyList();
		}
	}

	/**
	 * @param itemId the canonical item id (as returned by the examine menu click)
	 * @return the passive effect for this item, or null if it has none registered
	 */
	public PassiveEffect getForItemId(int itemId)
	{
		return effectsByItemId.get(itemId);
	}

	public Map<Integer, PassiveEffect> getAll()
	{
		return Collections.unmodifiableMap(effectsByItemId);
	}

	/**
	 * Exposed for tests / tooling: the list of data files this repository
	 * loads, so a validation test can iterate the same set independently
	 * of the runtime-merged map.
	 */
	public static List<String> getDataFiles()
	{
		return DATA_FILES;
	}
}

package com.betteritemexamine;

import com.google.inject.Provides;
import java.awt.Color;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Adds "hidden" passive effects (things that appear on the OSRS Wiki but
 * are NOT explained anywhere in-game, e.g. the Twisted Bow's accuracy/damage
 * scaling with target Magic level) onto an item's examine text.
 *
 * How it works:
 *  1. MenuOptionClicked fires when the player clicks "Examine" on an item.
 *     We stash that item's id.
 *  2. Shortly after, the game sends a ChatMessage of type ITEM_EXAMINE with
 *     the vanilla examine text. We intercept it, look up whether we have
 *     passive-effect data for that item id, and if so, append (or send as a
 *     separate message) our extra text.
 *
 * All the actual item data lives in passive_effects.json - see
 * PassiveEffectRepository. That's the file to edit/extend; this class should
 * rarely need to change.
 */
@Slf4j
@PluginDescriptor(
	name = "Better Item Examine",
	description = "Appends hidden/passive item effects (e.g. Twisted Bow's Magic-scaling accuracy/damage) "
		+ "to examine text, since these mechanics aren't explained in-game.",
	tags = {"examine", "items", "wiki", "passive", "twisted bow", "tooltip"}
)
public class BetterItemExaminePlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private BetterItemExamineConfig config;

	@Inject
	private PassiveEffectRepository passiveEffectRepository;

	/**
	 * Item id from the most recent "Examine" menu click, consumed by the
	 * next ITEM_EXAMINE chat message. -1 means "nothing pending".
	 *
	 * TODO(contributor): this naive single-slot approach assumes the next
	 * ITEM_EXAMINE message always corresponds to the last examine click.
	 * That holds for normal play but could theoretically race if something
	 * else generates an ITEM_EXAMINE message. A small FIFO queue would be a
	 * good first contribution if this ever proves unreliable.
	 */
	private int pendingExamineItemId = -1;

	@Provides
	BetterItemExamineConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BetterItemExamineConfig.class);
	}

	@Override
	protected void startUp()
	{
		passiveEffectRepository.load();
		pendingExamineItemId = -1;
	}

	@Override
	protected void shutDown()
	{
		pendingExamineItemId = -1;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!"Examine".equals(event.getMenuOption()))
		{
			return;
		}

		int itemId = event.getItemId();
		if (itemId <= 0)
		{
			return;
		}

		pendingExamineItemId = itemId;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.ITEM_EXAMINE)
		{
			return;
		}

		if (pendingExamineItemId == -1)
		{
			return;
		}

		int itemId = pendingExamineItemId;
		pendingExamineItemId = -1;

		PassiveEffect effect = passiveEffectRepository.getForItemId(itemId);
		if (effect == null)
		{
			return;
		}

		String addition = buildPassiveEffectText(effect);

		if (config.appendToExamineText())
		{
			String updated = event.getMessageNode().getValue() + " " + addition;
			event.getMessageNode().setValue(updated);
			client.refreshChat();
		}
		else
		{
			client.addChatMessage(ChatMessageType.CONSOLE, "", addition, null);
		}
	}

	private String buildPassiveEffectText(PassiveEffect effect)
	{
		Color color = config.highlightColor();
		String hex = String.format("%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
		return "<col=" + hex + ">[Passive: " + effect.getDescription() + "]</col>";
	}
}
